{"command": "python3 -c "
import json, subprocess, wave, numpy as np, base64

# Generate a 1-shot 441 Hz sine tone burst for 0.1s at 44100 Hz
fs = 44100
t = np.linspace(0, 0.1, int(fs*0.1), endpoint=False)
tone = (20000 * np.sin(2 * np.pi * 441 * t)).astype(np.int16)
pcm_b64 = base64.b64encode(tone.tobytes()).decode('ascii')

subprocess.run(['ft2', 'call', 'sample_create_from_pcm', json.dumps({
    'instrument': 3, 'sample': 0, 'pcm': pcm_b64, 'encoding': 'int16', 'name': 'Tone1Shot'
})])

subprocess.run(['ft2', 'call', 'sample_set', json.dumps({
    'instrument': 3, 'sample': 0, 'relative_note': 29, 'finetune': -34, 'volume': 64
})])

subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps({
    'pattern': 0, 'row': 0, 'channel': 0, 'note': 'C-4', 'instrument': 3, 'volume': 64
})])

subprocess.run(['ft2', 'call', 'module_render', json.dumps({
    'path': '/workspace/tune_test.wav', 'rate': 44100, 'bits': 16, 'amp': 1, 'loops': 1
})])

with wave.open('/workspace/tune_test.wav', 'rb') as w:
    data = np.frombuffer(w.readframes(w.getnframes()), dtype=np.int16)[::2].astype(float)

